parts.text:
Now add the padding cache + applyPadding. I'll add after the `byId` hydration block:
```js
const byId = new Map();
for (const el of document.querySelectorAll("[data-pathland-id]")) {
    byId.set(Number(el.getAttribute("data-pathland-id")), el);
}
```

Add after that:
```js
// Per-node padding state so edge modifiers can override the PADDING shorthand.
const pads = new Map();

function applyPadding(nodeId) {
    const el = byId.get(nodeId);
    if (!el) return;
    const p = pads.get(nodeId);
    const top = p.top ?? p.base;
    const right = p.right ?? p.base;
    const bottom = p.bottom ?? p.base;
    const left = p.left ?? p.base;
    el.style.paddingTop = top == null ? "" : `${top}px`;
    el.style.paddingRight = right == null ? "" : `${right}px`;
    el.style.paddingBottom = bottom == null ? "" : `${bottom}px`;
    el.style.paddingLeft = left == null ? "" : `${left}px`;
}
```

Then add the SET_PROPERTY handler cases. Let me do the edit.

