@Test
    void rendersModifierStyles() {
        View root = View.text("Hi")
                .padding(16)
                .color(Color.RED)
                .background(Color.BLUE)
                .fontSize(20f)
                .fontWeight(com.pathland.view.FontWeight.BOLD)
                .opacity(0.5f);
        String html = render(root).render(1);

        assertTrue(html.contains("padding-top:16px;padding-right:16px;padding-bottom:16px;padding-left:16px"));
        assertTrue(html.contains("color:rgba(255,0,0,1)"));
        assertTrue(html.contains("background-color:rgba(33,150,243,1)"));
        assertTrue(html.contains("font-size:20px"));
        assertTrue(html.contains("font-weight:bold"));
        assertTrue(html.contains("opacity:0.5"));
    }

    @Test
    void rendersEdgePaddingAndHidden() {
        View root = View.vstack(View.text("A"))
                .padding(24)
                .padding(0, 8, 0, 8)
                .visible(false);
        String html = render(root).render(1);

        assertTrue(html.contains("padding-top:0px;padding-right:8px;padding-bottom:0px;padding-left:8px"),
                "edge padding overrides the PADDING shorthand");
        assertTrue(html.contains("display:none"));
    }

    @Test
    void rendersFrameSizing() {
        View root = View.hstack(
